import React, { useEffect, useState, useRef } from "react";



import { getStore, updStore, gen16CodeId,  fetchEncryptStream, qryStore, ObjectKeys, parseDateMMDDYYYY } from "../../../stores/Utils";

import { CheckBoxSlide_Cmpt, TextInput_Cmpt, CheckBox_Cmpt, DropDwnPicker_Cmpt, SvgIcon_Cmpt } from "../../../components";


import "./dashboard.css"
import { CloseModal, OpenModal } from "../../../components/DialogHRM";
import AlertScanningInventory from "./AlertScanningInventory";
import { getInventoryById } from "../services/server_fetching";
import { OpenToast } from "../../../components/Toast";

const CheckBoxSlide = CheckBoxSlide_Cmpt();
const TextInput = TextInput_Cmpt();

const CheckBox = CheckBox_Cmpt();



const Svg = SvgIcon_Cmpt();

const frmNm = "do_inventory_location"

const DoInventoryByLoc  = ({ data, confirm }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);

	const inputScan = useRef(0);

	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			//updStore("scanningInventoryByLocation", hhhhh);
			//updStore("currentLocationOnScan", "JKdLryxsoWKkwmrY");
			set_obs(gen16CodeId())
		}
	});

	const updFrm = (f, v, k) => {
		let frm2 = getStore(frmNm) || {};
		if(k){
			if( !frm2[k]){
				frm2[k] = {};
			}
			frm2[k][f] = v;
		}else{
			frm2[f] = v;
		}
		updStore(frmNm, frm2);
		
		set_obs(gen16CodeId())
	};





	const save  = async ()  => {
		let ffm = getStore("scanningInventoryByLocation");
		//ffm["areaLocationId"] = gen16CodeId();
		let inventoryOnScanItems =  getStore("inventoryOnScanItems") || {};
		
		
		let list2invLoc = []

		ffm && ObjectKeys(ffm).map(locationId=>{
			ObjectKeys(ffm[locationId]).map(invId=>{
				if(inventoryOnScanItems?.[invId]){
					list2invLoc.push({
						inventoryId:invId,
						locationId,
						date: ffm[locationId][invId],
						productId: inventoryOnScanItems?.[invId]?.productId,
						alphaCode: inventoryOnScanItems?.[invId]?.alphaCode,
					})
				}
			})
		})
		
		let bdyq2 = {...getStore(qryStore())?.add_inv_location_batch};
		bdyq2.params = {
			businessId:  getStore("profileUser")?.businessId
		}

		// list2invLoc = hhhhh;
		bdyq2.form=list2invLoc;


		

		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		
		if (td) {
			//updStore("inventoryOnScanItems", {});
			// cb && cb(td[id]);
		}

		data?.modalID && CloseModal({id:data?.modalID});
		
		setTimeout(() => {
			updStore("inventoryOnScanItems", null);
			updStore("scanningInventoryByLocation", null);
			updStore(frmNm, null)
			set_obs(gen16CodeId());
			confirm && confirm();
			
		}, 400);

		
		
	};





	const clean = (f) => {
		updStore(frmNm, {});
		set_obs(gen16CodeId())
	};


	const addInventory = async (v) => {

		let hh = await getInventoryById(v);
		
		if(hh){
			let loc = getStore("currentLocationOnScan");
			let invBl = getStore("scanningInventoryByLocation") || {};
			if(!invBl[loc][v]){
				invBl[loc][v] = (new Date()).getTime();
			}
			updStore("scanningInventoryByLocation", invBl);
		}else{
			OpenToast({ text: "hubo un error con el codigo escaneado", timeout: 1500 });
		
		}
		
		set_obs(gen16CodeId());
	}

	const OnEnter = (v) => {
		
		if(getStore("locations_ids")[v]){
			updStore("currentLocationOnScan", v);
			let invBl = getStore("scanningInventoryByLocation") || {};
			if(!invBl[v]){
				invBl[v] = {};
			}
			updStore("scanningInventoryByLocation", invBl);
			set_obs(gen16CodeId())
		}else{
			if(getStore("currentLocationOnScan")){
				
				addInventory(v);
				
				
				
			}else{
				let msg = <div className="_dsplFlx ">
						<span>
							Debe escanear una locacion primero 
						</span>
					</div>
				
				AlertInv(msg);
				OpenToast({ text: "Debe escanear una locacion primero", timeout: 1500 });
			}
		}

		inputScan?.current?.clearTx();
		
	};


	

	const AlertInv =  (b) => {
		let dataModal = {};
		dataModal["zIndex"] = 450;
		dataModal["height"] = "80vh";
		// data['observeResize']=true;
		dataModal["props"] = { minHeight: "1vh", overlay: true };
		dataModal["content"] = 
			<AlertScanningInventory 
				msg={b}

			/>
		OpenModal(dataModal);
	}

	
	
	let scList = getStore("scanningInventoryByLocation");


	let currLocaList = scList?.[getStore("currentLocationOnScan")];

	return (
		<div style={{
			maxHeight: "90vh",
			minHeight: "86vh",
			width: "760px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px 39px"
		}}>
			<div className="_dsplFlx ">
				<p className="form_title">
				Inventory By Location
				</p>
				<div className="flexSpace"/>
				<div className="">
					<button onClick={save}>
						Guardar
					</button>
				</div>
			</div>

				{getStore("currentLocationOnScan")? 
				<div className={`lh-default hrm_themecolor blue_30`} style={{marginTop: 20}}>
					<div className="IssueLabel hrm_labelColor hrm_label_14lh">
						<div className="_dsplFlx keyToken fnt_curr_scan">
						
							{`Scanning this location ${`${getStore("locations_ids")?.[getStore("currentLocationOnScan")]?.areaId  }-${getStore("locations_ids")?.[getStore("currentLocationOnScan")]?.location  }`}`}
						</div>
					</div>
				</div>
				:null}
			
				<div className="_dsplFlx spaceAround" style={{marginTop:20}}>
					<TextInput  
						init={getStore(frmNm)?.["i2scan"]} 
						width={320} 
						updChanges={(e)=>updFrm("i2scan",e)}
						onEnter={OnEnter}
						ref={inputScan}
					/>
				</div>

			{currLocaList?
			<div className="">
				<ShowLocationList  
					locationId={getStore("currentLocationOnScan")}  
					locList={currLocaList}
					isCurrent={true}
				/>
			</div>
			:null}

			<div className="separator"></div>
			<div className="colScroll">
				{scList && ObjectKeys(scList).map(locationId=>{
					if(locationId === getStore("currentLocationOnScan")){
						return null;
					}

					return (
						<ShowLocationList  
							locationId={locationId}  
							locList={scList?.[locationId]}
							key={locationId}
						/>
					)
				})}
				
			</div>
			<div className="_dsplFlx " >
				<div className="flexSpace"/>
				

			</div>
		

			
		</div>
	);
};

export default DoInventoryByLoc;






const ShowLocationList = ({locationId, locList, isCurrent}) =>{


	return (
			<div key={locationId} >
				<div className={`lh-default hrm_themecolor ${isCurrent?"blue_30":"yellow_orange"}`} style={{marginTop: 20}}>
					<div className="IssueLabel hrm_labelColor hrm_label_14lh">
						<div className="_dsplFlx keyToken fnt_curr_scan ">
							<Svg
								name={"map-marker-radius-outline"} 
								color={"var(--lighten-color)"}
								size={20}
							/>
							{`${getStore("locations_ids")?.[locationId]?.areaId  }-${getStore("locations_ids")?.[locationId]?.location  }`}
						</div>
					</div>
				</div>
				
				{
					locList && ObjectKeys(locList).map(invId=>{
						return (
							<div key={invId} >
								{getStore("inventoryOnScanItems")?.[invId]?.alphaCode?
								<div className="invAlpha">
									<h5>
									{getStore("inventoryOnScanItems")?.[invId]?.alphaCode}
									</h5>
								</div>
								:
								<div className=" _dsplFlx ">
									<div className="flexSpace"/>
									<div className="invAlpha error _dsplFlx">
										<div className="icon">
											<Svg
												name={"alert"} 
												color={"#c62828"}
												size={20}
											/>
										</div>
										<h5>
										{invId}
										</h5>
									</div>
									<div className="flexSpace"/>
								</div>
								}
							</div>
						)
					})
				}
			</div>
		)
}